CREATE OR REPLACE FUNCTION finance_private.assert_closed_source_mutable(_tenant uuid, _table text, _row jsonb, _depth integer DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare account uuid;start_date date;end_date date;ref record;source_table text;source jsonb;identifier uuid;raw_date text;hit boolean:=false;outgoing public.finance_movements%rowtype;incoming public.finance_movements%rowtype;native jsonb;imp public.finance_statement_imports%rowtype;registered public.bank_accounts%rowtype;closed public.finance_account_period_closures%rowtype;anchor date;
begin
 if _row is null or _row='null'::jsonb then return;end if;
 if _table='employee_advances' and _row->>'status' is distinct from 'paid' and _row->>'paid_at' is null then return;end if;
 if _depth>8 then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
 if not finance_private.closed_interval_exists(_tenant,null,null,null) then return;end if;
 identifier:=nullif(_row->>'id','')::uuid;
 if exists(select 1 from public.finance_account_period_dependencies d join public.finance_account_period_closures c on c.tenant_id=d.tenant_id and c.id=d.closure_id where d.tenant_id=_tenant and d.source_kind=_table and d.source_id=identifier and d.dependency_role<>'composition_snapshot' and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
 account:=coalesce(nullif(_row->>'bank_account_id','')::uuid,nullif(_row->>'account_id','')::uuid);
 if account is not null and not exists(select 1 from public.bank_accounts a where a.tenant_id=_tenant and a.id=account) then account:=null;end if; if _table='finance_internal_transfers' then
  select * into outgoing from public.finance_movements where tenant_id=_tenant and id=(_row->>'outgoing_id')::uuid;
  select * into incoming from public.finance_movements where tenant_id=_tenant and id=(_row->>'incoming_id')::uuid;
  -- An already identified departure may arrive later. Its frozen leg stays intact.
  if finance_private.closed_interval_exists(_tenant,outgoing.bank_account_id,outgoing.occurred_on,outgoing.occurred_on) then
   if not exists(select 1 from public.finance_transfer_departures p where p.tenant_id=_tenant and p.outgoing_id=outgoing.id and p.destination_account_id=incoming.bank_account_id
    and not exists(select 1 from public.finance_account_period_closures c where c.tenant_id=_tenant and c.account_id=outgoing.bank_account_id and outgoing.occurred_on between c.period_start and c.period_end and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)
      and (incoming.occurred_on<=c.period_end or not exists(select 1 from public.finance_account_period_dependencies d where d.tenant_id=_tenant and d.closure_id=c.id and d.source_kind='finance_transfer_departures' and d.source_id=p.id)))) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
   perform finance_private.assert_closed_source_mutable(_tenant,'finance_movements',to_jsonb(incoming),_depth+1);return;
  end if;
 end if;
 if _table='finance_statement_verifications' then
  select * into imp from public.finance_statement_imports where tenant_id=_tenant and id=(_row->>'import_id')::uuid;
  native:=_row#>'{report,native_evidence}';
  if native is not null then
   if finance_private.closed_interval_exists(_tenant,imp.bank_account_id,(native#>>'{period,start,date}')::date,(native#>>'{period,end,date}')::date) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
   anchor:=(native#>>'{ledger_balance,as_of,date}')::date;
   for closed in select c.* from public.finance_account_period_closures c where c.tenant_id=_tenant and c.account_id=imp.bank_account_id and anchor between c.period_start and c.period_end and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id) loop
    select * into registered from public.bank_accounts where tenant_id=_tenant and id=imp.bank_account_id;
    if anchor is distinct from closed.period_end or native#>>'{ledger_balance,amount_cents}' is distinct from closed.snapshot#>>'{balances,closing_cents}'
     or native#>>'{ledger_balance,as_of,offset_minutes}' is distinct from '-180' or native#>>'{period,start,offset_minutes}' is distinct from '-180' or native#>>'{period,end,offset_minutes}' is distinct from '-180'
     or native->>'currency' is distinct from 'BRL' or native->>'parser_version' is distinct from 'native-ofx-v1'
     or native#>>'{account,bank_id}' is distinct from btrim(registered.bank_code) or native#>>'{account,branch_id}' is distinct from btrim(registered.branch_number) or native#>>'{account,account_id}' is distinct from btrim(registered.account_number)
     or native#>>'{account,account_type}' is distinct from (case registered.account_type when 'checking' then 'CHECKING' when 'savings' then 'SAVINGS' end)
     or _row->>'outcome' is distinct from 'rows_match' or _row#>>'{report,hash_verified}' is distinct from 'true' or _row#>>'{report,actual_hash}' is distinct from imp.file_hash or _row#>>'{report,identity_trust}' is distinct from 'native_file_identifier'
     or native->>'outside_declared_period' is distinct from 'false' or native->'repeated_bank_ids' is distinct from '[]'::jsonb
    then raise exception 'finance_closed_anchor_conflict' using errcode='55000';end if;
   end loop;
  end if;
 end if;
 if _table in('finance_statement_imports','finance_statement_coverage_approvals','finance_period_evidence_reviews','finance_legacy_cut_reviews') then
  start_date:=(_row->>'period_start')::date;end_date:=(_row->>'period_end')::date;
 elsif _table='finance_account_openings' then start_date:=(_row->>'effective_from')::date;end_date:=null;
 else
  raw_date:=coalesce(_row->>'occurred_on',_row->>'posted_on',_row->>'posted_at',_row->>'received_at',_row->>'paid_at',_row->>'effective_at',_row->>'payment_date',_row->>'advance_date',_row->>'occurred_at',_row->>'competence_date');
  if raw_date is not null then start_date:=(raw_date::timestamptz at time zone 'America/Sao_Paulo')::date;
   if raw_date ~ '^\d{4}-\d{2}-\d{2}$' then start_date:=raw_date::date;end if;end_date:=start_date;end if;
 end if;
 if start_date is not null or _table in('finance_movements','finance_bank_entries','bank_transactions','receivables_payments','payables_payments','driver_settlement_payments','closing_report_payments','load_payments','employee_advances','payroll_entry_items') then
  if finance_private.closed_interval_exists(_tenant,account,start_date,end_date) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
  hit:=true;
 end if;
 for ref in select key,value from jsonb_each_text(_row) where key in('import_id','first_import_id','row_id','review_id','group_id','opening_id','approval_id','bank_transaction_id','bank_entry_id','movement_id','outgoing_id','incoming_id','receivable_payment_id','payment_id') and value is not null loop
  source_table:=case ref.key when 'import_id' then case when _table='bank_transactions' then null else 'finance_statement_imports' end when 'first_import_id' then 'finance_statement_imports' when 'row_id' then 'finance_statement_rows' when 'review_id' then 'finance_statement_identity_reviews' when 'group_id' then 'finance_reconciliation_groups' when 'opening_id' then 'finance_account_openings' when 'approval_id' then 'finance_statement_coverage_approvals' when 'bank_transaction_id' then 'bank_transactions' when 'bank_entry_id' then 'finance_bank_entries' when 'movement_id' then 'finance_movements' when 'outgoing_id' then 'finance_movements' when 'incoming_id' then 'finance_movements' when 'receivable_payment_id' then 'receivables_payments' when 'payment_id' then case when _table='receivable_payment_reversals' then 'receivables_payments' end end;
  if source_table is not null then
   if _table='receivable_payment_reversals' and ref.key='payment_id' and start_date is not null then continue;end if;
   execute format('select to_jsonb(s) from public.%I s where s.tenant_id=$1 and s.id=$2',source_table) into source using _tenant,ref.value::uuid;
   if source is null then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
   perform finance_private.assert_closed_source_mutable(_tenant,source_table,source,_depth+1);hit:=true;
  end if;
 end loop;
 if _table='finance_reconciliation_groups' then
  for identifier in select value::uuid from jsonb_array_elements_text(_row->'movement_ids') loop select to_jsonb(m) into source from public.finance_movements m where m.tenant_id=_tenant and m.id=identifier;perform finance_private.assert_closed_source_mutable(_tenant,'finance_movements',source,_depth+1);end loop;
  for identifier in select value::uuid from jsonb_array_elements_text(_row->'bank_entry_ids') loop select to_jsonb(e) into source from public.finance_bank_entries e where e.tenant_id=_tenant and e.id=identifier;perform finance_private.assert_closed_source_mutable(_tenant,'finance_bank_entries',source,_depth+1);end loop;hit:=true;
 end if;
 if not hit then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
end$function$

CREATE OR REPLACE FUNCTION finance_private.check_movement_use()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.finance_movements%rowtype;p public.payables_payments%rowtype;issue text;begin
 if not finance_private.can_access(new.tenant_id) then raise exception 'finance_access_denied' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(new.tenant_id::text||':finance',0));
 if not finance_private.can_access(new.tenant_id) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into m from public.finance_movements where tenant_id=new.tenant_id and id=new.movement_id;
 if not found or m.direction<>'out' or m.nature='transfer' then raise exception 'finance_invalid_payment_movement' using errcode='22023';end if;
 if finance_private.movement_used_cents(new.tenant_id,new.movement_id)+new.amount_cents>m.amount_cents then raise exception 'finance_movement_overallocated' using errcode='23514';end if;
 if tg_table_name='finance_payable_movement_links' then
  if exists(select 1 from public.finance_payable_movement_links l where l.tenant_id=new.tenant_id and l.payment_id=new.payment_id
   and (l.origin='canonical' or new.origin='canonical' or not exists(select 1 from public.finance_payable_link_reversals r where r.tenant_id=l.tenant_id and r.link_id=l.id))) then
   raise exception 'finance_payment_already_linked' using errcode='23505';end if;
  select * into p from public.payables_payments where tenant_id=new.tenant_id and id=new.payment_id;
  if not found or p.payable_id is distinct from new.payable_id or p.amount is null or p.amount::text in('NaN','Infinity','-Infinity')
   or p.amount*100 is distinct from new.amount_cents::numeric or p.bank_account_id is distinct from m.bank_account_id then raise exception 'finance_payment_link_mismatch' using errcode='23514';end if;
  if new.origin='legacy_adoption' then
   issue:=finance_private.legacy_payable_payment_issue(new.tenant_id,new.payment_id);
   if issue is not null then raise exception '%',issue using errcode='23514';end if;
   if m.occurred_on is distinct from (p.paid_at at time zone 'America/Sao_Paulo')::date
    or exists(select 1 from public.payables title where title.tenant_id=new.tenant_id and title.id=p.payable_id and title.driver_id is not null and title.driver_id is distinct from m.driver_id) then raise exception 'finance_legacy_movement_mismatch' using errcode='23514';end if;
  elsif p.bank_transaction_id is not null then raise exception 'finance_payment_link_mismatch' using errcode='23514';end if;
 end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION finance_private.check_payable_payment_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.payables%rowtype;paid numeric;
begin
 if not finance_private.can_access(new.tenant_id) then raise exception 'finance_access_denied' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(new.tenant_id::text||':finance',0));
 select * into p from public.payables where id=new.payable_id and tenant_id=new.tenant_id for update;
 if not found or p.status='cancelled' then raise exception 'finance_payable_not_payable' using errcode='22023';end if;
 if new.amount is null or new.amount<=0 or new.amount<>trunc(new.amount,2) or new.amount::text in ('NaN','Infinity','-Infinity') then
  raise exception 'finance_invalid_payment_amount' using errcode='22023';end if;
 if not exists(select 1 from public.bank_accounts where tenant_id=new.tenant_id and id=new.bank_account_id) then
  raise exception 'finance_invalid_account' using errcode='22023';end if;
 select coalesce(sum(amount),0) into paid from finance_private.active_payable_payments where payable_id=p.id and tenant_id=p.tenant_id;
 if paid<0 or paid<>trunc(paid,2) or paid+new.amount>p.amount then raise exception 'finance_payable_overpaid' using errcode='23514';end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION finance_private.check_settlement_movement_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payment public.driver_settlement_payments%rowtype;driver uuid;m public.finance_movements%rowtype;
begin
 if not finance_private.can_access(new.tenant_id) then raise exception 'finance_access_denied' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(new.tenant_id::text||':finance',0));
 if not finance_private.can_access(new.tenant_id) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if exists(select 1 from public.finance_settlement_movement_links l where l.tenant_id=new.tenant_id and l.payment_id=new.payment_id
  and not exists(select 1 from public.finance_settlement_link_reversals r where r.tenant_id=l.tenant_id and r.link_id=l.id)) then
  raise exception 'finance_settlement_payment_already_linked' using errcode='23505';end if;
 select * into payment from public.driver_settlement_payments where id=new.payment_id and tenant_id=new.tenant_id for share;
 if not found or payment.settlement_id<>new.settlement_id or payment.amount*100<>new.amount_cents then raise exception 'finance_settlement_payment_mismatch' using errcode='23514';end if;
 select s.driver_id into driver from public.driver_settlements s where s.id=new.settlement_id and s.tenant_id=new.tenant_id for share;
 if not found or driver is null then raise exception 'finance_settlement_payment_mismatch' using errcode='23514';end if;
 select * into m from public.finance_movements where tenant_id=new.tenant_id and id=new.movement_id;
 if not found or m.direction<>'out' or m.nature='transfer' or m.driver_id is distinct from driver
 or payment.paid_at is null or m.occurred_on<>(payment.paid_at at time zone 'America/Sao_Paulo')::date then
  raise exception 'finance_settlement_movement_mismatch' using errcode='23514';end if;
 if finance_private.movement_used_cents(new.tenant_id,new.movement_id)+new.amount_cents>m.amount_cents then raise exception 'finance_movement_overallocated' using errcode='23514';end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION finance_private.movement_recording_origin(_tenant uuid, _movement uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.finance_movements%rowtype;c public.finance_commands%rowtype;e public.finance_events%rowtype;
 commands jsonb;events jsonb;snapshot jsonb;p jsonb;issue text;expected jsonb;
begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into m from public.finance_movements where tenant_id=_tenant and id=_movement;
 if not found then raise exception 'finance_movement_not_found' using errcode='22023';end if;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.request_id),'[]'::jsonb) into commands
 from public.finance_commands x where x.tenant_id=_tenant and x.action='record_movement' and finance_private.movement_origin_uuid(x.result->>'movement_id')=_movement;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]'::jsonb) into events
 from public.finance_events x where x.tenant_id=_tenant and x.entity_type='movement' and x.entity_id=_movement and x.action='recorded';
 snapshot:=jsonb_build_object('movement',to_jsonb(m),'recording_commands',commands,'recording_events',events);
 if jsonb_array_length(commands)=0 then issue:='recording_origin_unproven';
 elsif jsonb_array_length(commands)<>1 then issue:='recording_origin_ambiguous';
 else
  select * into c from public.finance_commands where tenant_id=_tenant and request_id=(commands->0->>'request_id')::uuid;
  p:=c.payload;
  if c.actor_id is distinct from m.created_by or jsonb_typeof(p) is distinct from 'object'
   or exists(select 1 from jsonb_object_keys(case when jsonb_typeof(p)='object' then p else '{}'::jsonb end) k
    where k not in('version','tenant_id','request_id','bank_account_id','direction','nature','amount_cents','occurred_on',
     'description','beneficiary_name','beneficiary_document','driver_id','bank_reference','receipt_path','reason'))
   or p->>'version' is distinct from '1' or finance_private.movement_origin_uuid(p->>'tenant_id') is distinct from _tenant or finance_private.movement_origin_uuid(p->>'request_id') is distinct from c.request_id
   or c.result @> jsonb_build_object('version',1,'tenant_id',_tenant,'request_id',c.request_id,'movement_id',_movement,'confirmed',true) is distinct from true
   or finance_private.movement_origin_uuid(p->>'bank_account_id') is distinct from m.bank_account_id
   or p->>'direction' is distinct from m.direction or p->>'nature' is distinct from m.nature
   or p->>'occurred_on' is distinct from m.occurred_on::text
   or btrim(p->>'description') is distinct from m.description
   or btrim(p->>'beneficiary_name') is distinct from m.beneficiary_name
   or nullif(btrim(p->>'beneficiary_document'),'') is distinct from m.beneficiary_document
   or finance_private.movement_origin_uuid(nullif(p->>'driver_id','')) is distinct from m.driver_id
   or (nullif(p->>'driver_id','') is not null and finance_private.movement_origin_uuid(p->>'driver_id') is null)
   or nullif(btrim(p->>'bank_reference'),'') is distinct from m.bank_reference
   or nullif(btrim(p->>'receipt_path'),'') is distinct from m.receipt_path
  then issue:='recording_origin_mismatch';
  elsif coalesce(p->>'amount_cents','') !~ '^[0-9]{1,14}$' then issue:='recording_origin_mismatch';
  elsif (p->>'amount_cents')::numeric<>m.amount_cents then issue:='recording_origin_mismatch';
  elsif jsonb_array_length(events)<>1 then issue:='recording_event_unproven';
  else
   select * into e from public.finance_events where tenant_id=_tenant and id=(events->0->>'id')::uuid;
   expected:=jsonb_build_object('id',m.id,'tenant_id',m.tenant_id,'bank_account_id',m.bank_account_id,
    'direction',m.direction,'nature',m.nature,'amount_cents',m.amount_cents,'occurred_on',m.occurred_on,
    'description',m.description,'beneficiary_name',m.beneficiary_name,'beneficiary_document',m.beneficiary_document,
    'driver_id',m.driver_id,'bank_reference',m.bank_reference,'receipt_path',m.receipt_path,'created_by',m.created_by);
   if e.actor_id is distinct from c.actor_id or e.reason is distinct from btrim(p->>'reason')
    or e.after_data @> expected is distinct from true then issue:='recording_event_mismatch';end if;
  end if;
 end if;
 return jsonb_build_object('version',1,'tenant_id',_tenant,'movement_id',_movement,
  'verified',issue is null,'issue',issue,'original_request_id',c.request_id,
  'revision',md5(snapshot::text),'snapshot',snapshot);
end$function$
